#include <cstring>

#include <zstd.h>
#include <vector>
#include <algorithm>
#include <bit>
#include <cstdio>
#include <cstdlib>
#include <chrono>
int main(int argc,char**argv){for(int f=1;f<argc;f++){int w,h;sscanf(strrchr(argv[f],'_')+1,"%dx%d",&w,&h);std::vector<unsigned short> raw(size_t(w)*h);FILE*fp=fopen(argv[f],"rb");fread(raw.data(),2,raw.size(),fp);fclose(fp);size_t total[4]={};auto start=std::chrono::steady_clock::now();for(int ty=0;ty<h/2;ty+=128)for(int tx=0;tx<w/2;tx+=128){int tw=std::min(128,w/2-tx),th=std::min(128,h/2-ty);std::vector<unsigned> best;size_t bestcost=-1;for(int mode=0;mode<5;mode++){std::vector<unsigned> u;size_t cost=0;for(int c=0;c<4;c++)for(int y=0;y<th;y++)for(int x=0;x<tw;x++){auto at=[&](int xx,int yy){return int(raw[(2*(ty+yy)+c/2)*w+2*(tx+xx)+c%2]);};int p=512;if(!y){if(x)p=at(x-1,y);}else if(!x)p=at(x,y-1);else{int L=at(x-1,y),U=at(x,y-1),UL=at(x-1,y-1),UR=at(std::min(x+1,tw-1),y-1);if(mode==0)p=(L+U+UL+UR+2)/4;else if(mode==1)p=std::clamp(L+U-UL,std::min(L,U),std::max(L,U));else if(mode==2)p=(L+U+1)/2;else if(mode==3)p=(2*L+U+UR+2)/4;else{int s=L;for(int dy=1;dy<=std::min(y,2);dy++)for(int dx=-2;dx<=2;dx++)s+=at(std::clamp(x+dx,0,tw-1),y-dy);int n=1+5*std::min(y,2);p=(s+n/2)/n;}}int e=at(x,y)-p;u.push_back(e<0?-2*e-1:2*e);}for(size_t i=0;i<u.size();i+=64){size_t end=std::min(i+64,u.size());unsigned sum=0;for(size_t j=i;j<end;j++)sum+=u[j];int k=std::max(0,int(std::bit_width(unsigned(sum/(end-i))))-2);unsigned qs=0;for(size_t j=i;j<end;j++)qs+=u[j]>>k;cost+=(end-i)*(k+1)+qs;}if(cost<bestcost){bestcost=cost;best=std::move(u);}}for(int variant=0;variant<4;variant++){std::vector<unsigned char>q;size_t bits=0;for(size_t i=0;i<best.size();i+=64){size_t end=std::min(i+64,best.size());unsigned sum=0,mx=0;for(size_t j=i;j<end;j++){sum+=best[j];mx=std::max(mx,best[j]);}int k=std::max({0,int(std::bit_width(unsigned(sum/(end-i))))-2+variant,int(std::bit_width(mx))-8});bits+=(end-i)*k+8;for(size_t j=i;j<end;j++)q.push_back(best[j]>>k);}std::vector<unsigned char>out(ZSTD_compressBound(q.size()));size_t n=ZSTD_compress(out.data(),out.size(),q.data(),q.size(),1);total[variant]+=(bits+7)/8+n+8;}}printf("%s %zu %zu %zu %zu %.1fms\n",argv[f],total[0],total[1],total[2],total[3],std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count());fflush(stdout);}}
